// Relational Database Engine Simulation inside n8n
// Initializes relational schemas, primary/foreign key constraints, and seed data
let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}

// 1. DDL: Create Tables & Constraints
staticData.tables = staticData.tables || {};
staticData.tables.customers = [
  { customerId: "CUST-001", name: "Acme Corp", creditLimit: 5000.00, currentBalance: 1200.00 },
  { customerId: "CUST-002", name: "Globex Inc", creditLimit: 500.00, currentBalance: 450.00 }
];
staticData.tables.orders = [];
staticData.tables.order_items = [];

return [
  {
    json: {
      status: "DATABASE_INITIALIZED",
      schema: {
        tables: ["customers", "orders", "order_items"],
        constraints: [
          "PK_customers_customerId",
          "PK_orders_orderId",
          "FK_orders_customers",
          "PK_order_items_itemId",
          "FK_order_items_orders",
          "CHECK_credit_limit"
        ],
        indexes: ["idx_orders_customer", "idx_items_order"]
      },
      seededCustomers: staticData.tables.customers.length,
      initializedAt: new Date().toISOString()
    }
  }
];

// Stage incoming multi-item order payload for database transaction
// Customer CUST-001 (Acme Corp): Limit $5,000.00, Balance $1,200.00
// Order Total: 2 * 450 + 5 * 75 = 900 + 375 = $1,275.00
// Projected Balance: $2,475.00 <= $5,000.00 (Passes constraint check)
return [
  {
    json: {
      orderId: "ORD-DB-5001",
      customerId: "CUST-001",
      orderDate: new Date().toISOString().split('T')[0],
      lineItems: [
        {
          sku: "SKU-SRV-01",
          description: "Cloud Managed Server",
          quantity: 2,
          unitPrice: 450.00
        },
        {
          sku: "SKU-LIC-02",
          description: "Enterprise Security Seat",
          quantity: 5,
          unitPrice: 75.00
        }
      ]
    }
  }
];

// Parameterized Order Header Insert Simulation
// Computes total order value and safely inserts parent header with PENDING status
const order = $input.item.json;
const lineItems = order.lineItems || [];
const totalAmount = Number(lineItems.reduce((acc, it) => acc + (it.quantity * it.unitPrice), 0).toFixed(2));

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}
staticData.orders = staticData.orders || [];

const orderRecord = {
  orderId: order.orderId,
  customerId: order.customerId,
  orderDate: order.orderDate,
  totalAmount: totalAmount,
  status: "PENDING",
  createdAt: new Date().toISOString()
};

// Insert or update order header
const existingIdx = staticData.orders.findIndex(o => o.orderId === order.orderId);
if (existingIdx !== -1) {
  staticData.orders[existingIdx] = orderRecord;
} else {
  staticData.orders.push(orderRecord);
}

return {
  json: {
    ...order,
    headerInserted: true,
    totalAmount: totalAmount,
    status: "PENDING"
  }
};

// Batch Insert Child Order Items with Foreign Key Reference
// Enforces referential integrity by associating each item to orderId
const order = $input.item.json;
const lineItems = order.lineItems || [];

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}
staticData.orderItems = staticData.orderItems || [];

// Remove previous items for this orderId if any
staticData.orderItems = staticData.orderItems.filter(i => i.orderId !== order.orderId);

const insertedItems = lineItems.map((it, idx) => {
  const lineTotal = Number((it.quantity * it.unitPrice).toFixed(2));
  const record = {
    itemId: "ITEM-" + order.orderId + "-" + (idx + 1),
    orderId: order.orderId, // Foreign Key
    sku: it.sku,
    description: it.description,
    quantity: it.quantity,
    unitPrice: it.unitPrice,
    lineTotal: lineTotal
  };
  staticData.orderItems.push(record);
  return record;
});

return {
  json: {
    orderId: order.orderId,
    customerId: order.customerId,
    orderDate: order.orderDate,
    totalAmount: order.totalAmount,
    itemsCount: insertedItems.length,
    items: insertedItems,
    itemsInserted: true
  }
};

// ACID Transaction Enforcer: Credit Limit Constraint Validation
// Evaluates CHECK constraint: (currentBalance + totalAmount) <= creditLimit
const order = $input.item.json;

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}

const customers = (staticData.tables && staticData.tables.customers) || [
  { customerId: "CUST-001", name: "Acme Corp", creditLimit: 5000.00, currentBalance: 1200.00 },
  { customerId: "CUST-002", name: "Globex Inc", creditLimit: 500.00, currentBalance: 450.00 }
];

const customer = customers.find(c => c.customerId === order.customerId);

if (!customer) {
  return {
    json: {
      isCommitted: false,
      transactionStatus: "ROLLED_BACK",
      reason: "CUSTOMER_NOT_FOUND",
      orderId: order.orderId,
      customerId: order.customerId
    }
  };
}

const projectedBalance = Number((customer.currentBalance + order.totalAmount).toFixed(2));

// Enforce CHECK Constraint: balance cannot exceed credit limit
if (projectedBalance > customer.creditLimit) {
  // ROLLBACK: Delete pending order header and orphaned line items
  if (staticData.orders) {
    staticData.orders = staticData.orders.filter(o => o.orderId !== order.orderId);
  }
  if (staticData.orderItems) {
    staticData.orderItems = staticData.orderItems.filter(i => i.orderId !== order.orderId);
  }

  return {
    json: {
      isCommitted: false,
      transactionStatus: "ROLLED_BACK",
      reason: "CREDIT_LIMIT_EXCEEDED",
      orderId: order.orderId,
      customerId: customer.customerId,
      customerName: customer.name,
      currentBalance: customer.currentBalance,
      attemptedCharge: order.totalAmount,
      projectedBalance: projectedBalance,
      creditLimit: customer.creditLimit,
      rolledBackAt: new Date().toISOString()
    }
  };
}

// COMMIT: Update customer balance and finalize order status to COMMITTED
const previousBalance = customer.currentBalance;
customer.currentBalance = projectedBalance;

if (staticData.orders) {
  const ord = staticData.orders.find(o => o.orderId === order.orderId);
  if (ord) ord.status = "COMMITTED";
}

return {
  json: {
    isCommitted: true,
    transactionStatus: "COMMITTED",
    orderId: order.orderId,
    customerId: customer.customerId,
    customerName: customer.name,
    previousBalance: previousBalance,
    updatedBalance: projectedBalance,
    creditLimit: customer.creditLimit,
    orderTotal: order.totalAmount,
    committedAt: new Date().toISOString()
  }
};

// Rollback Telemetry & Security Incident Logger
// Formats audit record when a database transaction is aborted due to constraint violations
const details = $input.item.json;

return {
  json: {
    auditEvent: "ACID_TRANSACTION_ABORTED",
    status: "ROLLED_BACK_SAFELY",
    orderId: details.orderId,
    customerId: details.customerId,
    reason: details.reason,
    attemptedAmount: details.attemptedCharge,
    creditLimit: details.creditLimit,
    currentBalance: details.currentBalance,
    orphanedRecordsPurged: true,
    loggedAt: new Date().toISOString()
  }
};

// Indexed SQL Relational JOIN Simulation:
// SELECT o.*, c.name, c.currentBalance, i.*
// FROM orders o
// JOIN customers c ON o.customerId = c.customerId
// JOIN order_items i ON o.orderId = i.orderId
// WHERE o.orderId = $1;
const trans = $input.item.json;
const orderId = trans.orderId;

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}

const orders = staticData.orders || [
  {
    orderId: orderId,
    customerId: trans.customerId,
    orderDate: new Date().toISOString().split('T')[0],
    totalAmount: trans.orderTotal,
    status: "COMMITTED"
  }
];

const customers = (staticData.tables && staticData.tables.customers) || [
  { customerId: "CUST-001", name: "Acme Corp", creditLimit: 5000.00, currentBalance: trans.updatedBalance }
];

const orderItems = staticData.orderItems || [
  { itemId: "ITEM-" + orderId + "-1", orderId: orderId, sku: "SKU-SRV-01", description: "Cloud Managed Server", quantity: 2, unitPrice: 450.00, lineTotal: 900.00 },
  { itemId: "ITEM-" + orderId + "-2", orderId: orderId, sku: "SKU-LIC-02", description: "Enterprise Security Seat", quantity: 5, unitPrice: 75.00, lineTotal: 375.00 }
];

const order = orders.find(o => o.orderId === orderId) || { orderId, customerId: trans.customerId, totalAmount: trans.orderTotal, status: "COMMITTED" };
const customer = customers.find(c => c.customerId === order.customerId) || { customerId: order.customerId, name: trans.customerName || "Acme Corp", currentBalance: trans.updatedBalance };
const matchingItems = orderItems.filter(i => i.orderId === orderId);

return {
  json: {
    orderId: order.orderId,
    orderDate: order.orderDate,
    status: order.status,
    totalAmount: order.totalAmount,
    customer: {
      customerId: customer.customerId,
      name: customer.name,
      creditLimit: customer.creditLimit || trans.creditLimit,
      currentBalance: customer.currentBalance
    },
    lineItems: matchingItems,
    joinedAt: new Date().toISOString()
  }
};

// Master Transaction Audit Formatter
// Confirms ACID durability and generates tamper-evident transaction receipt
const item = $input.item.json;

return {
  json: {
    auditStatus: "DATABASE_TRANSACTION_VERIFIED",
    auditEvent: "ACID_TRANSACTION_COMMITTED",
    orderId: item.orderId,
    customerName: item.customer.name,
    customerId: item.customer.customerId,
    persistedTotal: item.totalAmount,
    lineItemCount: item.lineItems.length,
    customerBalanceAfterCommit: item.customer.currentBalance,
    databaseStatus: "CONSISTENT",
    verifiedAt: new Date().toISOString()
  }
};
